// impl is never exported by name; it is only referenced inside the
// initializer of another export (`handlers`). That reference is INTERNAL
// use, not export plumbing — stubbing impl's body would break handlers.run.
function impl(input) {
  const normalized = String(input ?? '').trim().toLowerCase();
  const parts = normalized.split(/\s+/).filter((p) => p.length > 0);
  const counts = new Map();
  for (const part of parts) {
    counts.set(part, (counts.get(part) ?? 0) + 1);
  }
  const summary = [...counts.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([word, n]) => `${word}:${n}`)
    .join(',');
  return `handled(${summary})`;
}

export const handlers = { run: impl };
